$ErrorActionPreference = 'Stop'
if ([Threading.Thread]::CurrentThread.ApartmentState -ne [Threading.ApartmentState]::STA) { throw 'Run with powershell.exe -STA.' }
$halcon = 'C:\Program Files\MVTec\HALCON-20.11-Progress'; $env:PATH = (Join-Path $halcon 'bin\x64-win64') + ';' + $env:PATH
Add-Type -AssemblyName PresentationFramework
Add-Type -AssemblyName System.Drawing
Add-Type -AssemblyName System.Windows.Forms
[Reflection.Assembly]::LoadFrom((Join-Path $halcon 'bin\dotnet35\halcondotnet.dll')) | Out-Null
$assembly = [Reflection.Assembly]::LoadFrom((Join-Path $ProjectRoot 'bin\x64\Debug\HalconWinFormsDemo.exe'))
function Assert([bool]$ok,[string]$message){if(-not $ok){throw "Assertion failed: $message"}}
function Pump([int]$ms){$frame=New-Object Windows.Threading.DispatcherFrame;$timer=New-Object Windows.Threading.DispatcherTimer;$timer.Interval=[TimeSpan]::FromMilliseconds($ms);$timer.Add_Tick({$timer.Stop();$frame.Continue=$false});$timer.Start();[Windows.Threading.Dispatcher]::PushFrame($frame)}
function Shot([string]$path){[IO.Directory]::CreateDirectory((Split-Path -Parent $path))|Out-Null;$window.UpdateLayout();$root=$window.Content;$top=$root.PointToScreen([Windows.Point]::new(0,0));$end=$root.PointToScreen([Windows.Point]::new($root.ActualWidth,$root.ActualHeight));$screen=[Windows.Forms.Screen]::FromPoint([Drawing.Point]::new([int]$top.X,[int]$top.Y)).Bounds;$bmp=New-Object Drawing.Bitmap([int][Math]::Min($end.X-$top.X,$screen.Right-$top.X),[int][Math]::Min($end.Y-$top.Y,$screen.Bottom-$top.Y));$g=[Drawing.Graphics]::FromImage($bmp);try{$g.CopyFromScreen([int]$top.X,[int]$top.Y,0,0,$bmp.Size);$bmp.Save($path,[Drawing.Imaging.ImageFormat]::Png)}finally{$g.Dispose();$bmp.Dispose()}}
$mainType=$assembly.GetType('HalconWinFormsDemo.MainWindow',$true);$serviceType=$assembly.GetType('HalconWinFormsDemo.Services.RecipeService',$true);$loggerType=$assembly.GetType('HalconWinFormsDemo.Services.AppLogger',$true);$kindType=$assembly.GetType('HalconWinFormsDemo.Models.VmToolKind',$true);$metadataType=$assembly.GetType('HalconWinFormsDemo.Models.ToolMetadata',$true);$roiType=$assembly.GetType('HalconWinFormsDemo.Models.RoiData',$true)
$private=[Reflection.BindingFlags]'Instance,NonPublic';$all=[Reflection.BindingFlags]'Instance,NonPublic,Public';$staticPublic=[Reflection.BindingFlags]'Static,Public';$temp=Join-Path([IO.Path]::GetTempPath())('halcon-s84-'+[Guid]::NewGuid().ToString('N'));[IO.Directory]::CreateDirectory($temp)|Out-Null
$service=$serviceType.GetConstructor([Type[]]@([string])).Invoke([object[]]@($temp.ToString()));$logger=$loggerType.GetConstructor([Type[]]@([string])).Invoke([object[]]@($temp.ToString()));$window=$mainType.GetConstructor($private,$null,[Type[]]@($serviceType,$loggerType),$null).Invoke([object[]]@($service,$logger))
function F([string]$name){$field=$mainType.GetField($name,$all);if($null-eq$field){throw "Missing field $name"};$value=$field.GetValue($window);Write-Output -NoEnumerate $value}
function M([string]$name,[object[]]$invokeArgs=@()){try{$method=$mainType.GetMethods($private)|Where-Object Name -eq $name|Where-Object{$_.GetParameters().Count-eq$invokeArgs.Count}|Select-Object -First 1;if($null-eq$method){throw "Missing $name/$($invokeArgs.Count)"};$method.Invoke($window,$invokeArgs)} catch [Reflection.TargetInvocationException]{throw $_.Exception.InnerException}}
function Tool([string]$kind,[string]$name){M 'CreateFlowTool' @([Enum]::Parse($kindType,$kind),$name,$true,$null)}
function Execute($tool){M 'ExecuteFlowTool' @($tool,'S84 smoke')}
function Out($tool,[string]$port){$value=$null;if(-not$tool.TryGetOutputValue($port,[ref]$value)){throw "Missing output $port"};Write-Output -NoEnumerate $value}
function RowShown([string]$controlName){$control=F $controlName;$grid=$control;while($null-ne$grid-and-not($grid-is[Windows.Controls.Grid])){$grid=[Windows.LogicalTreeHelper]::GetParent($grid)};$row=[Windows.Controls.Grid]::GetRow($control);$grid.RowDefinitions[$row].Height.Value-gt 0}
$app=[Windows.Application]::Current;if($null-eq$app){$app=New-Object Windows.Application;$app.ShutdownMode=[Windows.ShutdownMode]::OnExplicitShutdown}
try{
 $window.Topmost=$true;$window.WindowState=[Windows.WindowState]::Normal;$window.MinWidth=0;$window.MinHeight=0;$window.Left=0;$window.Top=0;$window.Width=1366;$window.Height=768;$window.Show();Pump 650
 $flow=F 'flowTools';M 'DisposeFlowTools'|Out-Null;$flow.Clear();$source=Tool ImageSource 'Input';$auto=Tool AutomaticThreshold 'Auto threshold';$morph=Tool RegionMorphology 'Clean region';$judge=Tool NumericJudge 'Threshold judge';$xld=Tool XldCircleFitting 'Circle fit'
 foreach($tool in @($source,$auto,$morph,$judge,$xld)){$flow.Add($tool)}
 $source.Parameters.LocalImagePath=Join-Path $env:PUBLIC 'Documents\MVTec\HALCON-20.11-Progress\examples\images\barcode\code128\code12801.png';$source.Parameters.LocalImageSerialNumber='S84-AUTO';$auto.SetInputBinding('Image',$source.ToolId,'Image');$morph.SetInputBinding('Region',$auto.ToolId,'Region');$judge.SetInputBinding('Value',$auto.ToolId,'Threshold');$judge.InputToolId=$auto.ToolId;$judge.InputPortName='Threshold';$judge.NumericLowerLimit=1;$judge.NumericUpperLimit=254
 Assert((F 'toolCatalog').Count -ge 75) 'Catalog lost the S84 baseline tools'
 $kind=[Enum]::Parse($kindType,'AutomaticThreshold');$inputs=$metadataType.GetMethod('GetInputPorts',$staticPublic).Invoke($null,[object[]]@($kind));$outputs=$metadataType.GetMethod('GetOutputPorts',$staticPublic).Invoke($null,[object[]]@($kind));$imagePort=@($inputs|Where-Object { $_.PortName -eq 'Image' })[0];Assert($null -ne $imagePort -and $imagePort.DataType -eq 'Image') 'Typed Image input missing';foreach($port in @('Region','Area','RegionCount','Threshold','Polarity','Parameters','ResultCode')){Assert(@($outputs|Where-Object { $_.PortName -eq $port }).Count -eq 1) "Output $port missing"};$thresholdPort=@($outputs|Where-Object { $_.PortName -eq 'Threshold' })[0];Assert($thresholdPort.DataType -eq 'Number') 'Threshold is not Number'
 $profiles=$mainType.GetField('TaskCommonParameterProfilesS83',[Reflection.BindingFlags]'Static,NonPublic').GetValue($null);Assert($profiles.Count-ge 40) 'Task profile coverage is too small'
 Execute $source|Out-Null;Execute $auto|Out-Null;Execute $morph|Out-Null;Execute $judge|Out-Null;$threshold=[double](Out $auto Threshold);$firstRegion=Out $auto Region;Assert($auto.ResultCode-eq'OK'-and$threshold-gt0-and$threshold-lt255-and[double](Out $auto RegionCount)-ge1-and-not$firstRegion.IsDisposed) 'Dark automatic threshold chain failed';Assert($morph.ResultCode-eq'OK'-and$judge.ResultCode-eq'OK') 'Region/Number downstream failed'
 $width=[double](Out $source Width);$height=[double](Out $source Height);$geometry=$roiType.GetMethod('CreateRectangle',$staticPublic).Invoke($null,[object[]]@([double]0,[double]0,[double]($height-1),[double]($width-1)));$roi=M 'AddRoiLayer' @($geometry,'S84 detection',$auto);$geometry.Dispose();Execute $auto|Out-Null;Assert($firstRegion.IsDisposed) 'Old managed Region was not released on rerun';Assert(([string](Out $auto Parameters)).Contains('ROI-')) 'ROI effective-domain execution was not reported'
 $auto.Parameters.AutomaticThresholdPolarity='Light';Execute $auto|Out-Null;Assert((Out $auto Polarity) -eq 'Light') 'Light polarity did not run';$recipe=M 'CaptureRecipe';$saved=@($recipe.ToolFlow|Where-Object { $_.ToolId -eq $auto.ToolId })[0];Assert($null -ne $saved -and $saved.Parameters.AutomaticThresholdPolarity -eq 'Light') 'Polarity did not persist in recipe';$clone=$auto.Parameters.Clone();Assert($clone.AutomaticThresholdPolarity -eq 'Light') 'Polarity did not clone'
 M 'OpenCentralModuleConfigurationS77' @($auto)|Out-Null;$autoSummary=(F 'DockKeyParameterSummaryText').Text;Assert($autoSummary -match '1') "Automatic threshold first screen is not one decision: $autoSummary";Assert((RowShown 'DockAutomaticThresholdPolarityComboBox')) 'Polarity is hidden';Assert(-not (F 'DockAdvancedParameterToggleButton').IsEnabled) 'Automatic threshold exposes fake advanced fields';Pump 350;Shot $Capture1366
 $window.Width=1938;$window.Height=1158;Pump 400;M 'OpenCentralModuleConfigurationS77' @($xld)|Out-Null;Assert((F 'DockKeyParameterSummaryText').Text -match '[1-4]') 'XLD task profile missing';Assert((RowShown 'DockXldCircleFitAlgorithmComboBox') -and -not (RowShown 'DockXldCircleFitIterationsTextBox')) 'XLD common/advanced split is wrong';Pump 300;Shot $Capture1938
 $source.ClearRuntimeOutputs();$source.ResultCode='--';$staleRejected=$false;try{Execute $auto|Out-Null}catch{$staleRejected=$_.Exception.Message.Contains('Image') -or $_.Exception.Message.Contains('OK')};$stale=$null;Assert($staleRejected -and -not $auto.TryGetOutputValue('Threshold',[ref]$stale)) 'Stale input did not invalidate automatic threshold outputs'
 Write-Output "S84_AUTOMATIC_THRESHOLD=PASS; Catalog=75; Profiles=$($profiles.Count); Threshold=$threshold; ROI=True; Downstream=Region+Number; Recipe=True; Captures=$Capture1366,$Capture1938"
} finally { try{$mainType.GetField('recipeCloseConfirmed',$private).SetValue($window,$true);$window.Close();$app.Shutdown()} catch{}; if(Test-Path $temp){Remove-Item -LiteralPath $temp -Recurse -Force} }
